sys_ws_operation.operation_script:
(function process(request, response) {
    var requestBody = request.body.nextEntry();

    // 1. Extract and parse incoming sensor values safely
    var vaultId = requestBody.sensor_id || requestBody.vault_id || "UNKNOWN_VAULT";

    // Support both formatting types (inches from your script vs cm from standard IoT data)
    var waterLevel = parseFloat(requestBody.water_level_inches) || parseFloat(requestBody.telemetry ? requestBody.telemetry.water_level_cm : 0.0) || 0.0;
    var tempC = parseInt(requestBody.vault_temp_c, 10) || parseInt(requestBody.telemetry ? requestBody.telemetry.transformer_temp_c : 0, 10) || 0;

    var pumpStatus = requestBody.pump_status || (requestBody.telemetry ? requestBody.telemetry.pump_status : "UNKNOWN");
    pumpStatus = pumpStatus ? pumpStatus.toUpperCase() : "UNKNOWN";

    // 2. Enforce Data Idempotency (MD5 Hash Check to prevent duplicate processing)
    var stringPayload = JSON.stringify(requestBody);
    var crypt = typeof GlideDigest == 'undefined' ? new CertificateEncryption() : new GlideDigest();
    var payloadHash = crypt.getMD5Hex(stringPayload);

    // Check against your Incident table to prevent double-firing active emergencies
    var checkDup = new GlideRecord('x_704340_metro_v_0_vault_safety_incident'); 
    checkDup.addQuery('u_payload_hash', payloadHash);
    checkDup.addQuery('active', true); 
    checkDup.query();

    if (checkDup.next()) {
        response.setStatus(200);
        response.setBody({
            "status": "Ignored",
            "message": "Duplicate active telemetry payload detected. Suppressing duplicate execution to protect system resources."
        });
        return;
    }

    // 3. Operational Filtering / Threshold Logic (Cost & Performance Optimization)
    // Safe Threshold Parameters: Low water AND safe temperature AND operating pump
    var IS_WATER_SAFE = (waterLevel <= 6.0); // Safe threshold example: Under 6 inches
    var IS_TEMP_SAFE = (tempC <= 50);        // Safe threshold example: Under 50°C
    var IS_PUMP_SAFE = (pumpStatus === "IDLE" || pumpStatus === "RUNNING");

    if (IS_WATER_SAFE && IS_TEMP_SAFE && IS_PUMP_SAFE) {
        // Log the clean tracking telemetry to a background data table for compliance auditing
        var telemetryLog = new GlideRecord('x_704340_metro_v_0_telemetry_vault_logs'); 
        if (telemetryLog.isValid()) {
            telemetryLog.initialize();
            telemetryLog.vault_id = vaultId;
            telemetryLog.water_level = waterLevel.toString();
            telemetryLog.temperature = tempC.toString();
            telemetryLog.pump_status = pumpStatus;
            telemetryLog.evaluation = "NORMAL - Operational boundaries maintained. AI evaluation bypassed.";
            telemetryLog.insert();
        }

        // Return a clean operational response. No downstream incidents or AI processing needed!
        response.setStatus(200);
        response.setBody({
            "status": "Success",
            "evaluation": "Normal operating environment tracked.",
            "vault_incident_created": "NONE"
        });
        return;
    }

    // 4. Anomaly Detected Workflow: Create Vault Safety Incident for OpenAI to process asynchronously
    var gr = new GlideRecord('x_704340_metro_v_0_vault_safety_incident'); 
    gr.initialize();
    gr.short_description = "CRITICAL: Telemetry Anomaly detected at " + vaultId;

    // Construct a highly clean string layout for your downstream Async OpenAI business rule to parse perfectly
    gr.description = "VAULT_ID: " + vaultId + "\n" +
                     "WATER_LEVEL: " + waterLevel + "\n" +
                     "TEMPERATURE_CELSIUS: " + tempC + "\n" +
                     "PUMP_STATE: " + pumpStatus + "\n" +
                     "METRICS_BREACHED: " + (!IS_WATER_SAFE ? "[Water Level] " : "") + (!IS_TEMP_SAFE ? "[Temperature] " : "") + (!IS_PUMP_SAFE ? "[Pump Failure] " : "");

    gr.u_payload_hash = payloadHash;

    var createdSysId = gr.insert();

    // Respond back to the sensor confirming the emergency ticket has safely triggered the AI Engine pipeline
    var res = {
        "status": "Anomaly Detected",
        "evaluation": "Metrics exceeded safety limits. Operational record safely dispatched to the GenAI Diagnostic Engine.",
        "vault_incident_created": createdSysId
    };

    response.setBody(res);
    response.setStatus(201);

})(request, response);
